try {
  const text = $input.first().json.text;
  if (!text || text.trim() === '') {
    throw new Error('No dissertation text received - input was empty after extraction');
  }
  const body = $('Webhook Trigger').first().json.body || {};
  const review_type = (body.review_type || 'full_review').trim().toLowerCase();
  const valid = ['literature_review', 'literature_methodology', 'full_review'];
  const resolved_type = valid.includes(review_type) ? review_type : 'full_review';
  return { json: { text: text.trim(), run_id: Date.now(), review_type: resolved_type } };
} catch (e) {
  throw new Error('Code: Input Validator: ' + e.message);
}

try {
  const rawText = $input.first().json.text;
  const cleanedText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  const macro_context = JSON.parse(cleanedText);
  const required = ['title','sections_identified','thesis_statement','argument_chain','stated_methodology','key_variables_or_concepts','target_audience_or_field'];
  for (const f of required) {
    if (!macro_context[f]) throw new Error('Missing required field: ' + f);
  }
  // FIX 2: Stamp run_id into macro_context so it flows through every section item
  // and enables contamination filtering in Code: Merge All Feedback
  macro_context.run_id = $node["Code: Input Validator"].json.run_id;
    macro_context.review_type = $node["Code: Input Validator"].json.review_type || 'full_review';
  macro_context.run_id = $node["Code: Input Validator"].json.run_id || Date.now();
  return { json: { macro_context: macro_context, original_text: $node["Code: Input Validator"].json.text } };
} catch (e) {
  throw new Error('Code: Parse Macro Context: JSON parse/validation failed — ' + e.message);
}

try {
  const text = $input.first().json.original_text;
  const macroContext = $input.first().json.macro_context;
  // FIX 4: Strict line-anchored regex — $ ensures only full-line headings match, never mid-paragraph words
  const headingRegex = /^[ \t]*(?:\d+\.?\s+)?(?:Abstract|Introduction|Literature\s+Review|Background|Methodology|Methods|Results(?:\s+and\s+Analysis)?|Findings|Discussion|Conclusion|Limitations|References|Bibliography|Appendix)[ \t]*[:\-]?[ \t]*$/gim;
  let match, indices = [];
  while ((match = headingRegex.exec(text)) !== null) {
    indices.push({ name: match[0].trim(), index: match.index });
  }
  let sections = [];
  if (indices.length === 0) {
    // No headings found — treat whole text as one section
    sections.push({ section_name: 'Full Document', section_text: text, next_context: '', macro_context: macroContext });
  } else {
    for (let i = 0; i < indices.length; i++) {
      const start = indices[i].index;
      const end = (i + 1 < indices.length) ? indices[i+1].index : text.length;
      const content = text.substring(start, end).replace(indices[i].name, '').trim();
      // Raised minimum to 200 chars to filter any remaining short fragments
      if (content.length >= 200) {
        sections.push({ section_name: indices[i].name, section_text: content, next_context: '', macro_context: macroContext });
      }
    }
  }
  // Ultimate fallback — guarantees at least 1 item always
  if (sections.length === 0) {
    sections.push({ section_name: 'Full Document', section_text: text, next_context: '', macro_context: macroContext });
  }
  const scopeKeywords = {
    literature_review:      ['literature', 'background', 'theoretical', 'conceptual', 'review', 'prior research', 'related work'],
    literature_methodology: ['literature', 'background', 'review', 'method', 'methodology', 'research design', 'sampling', 'data collection'],
    full_review: null
  };
  const reviewType = (macroContext && macroContext.review_type)
    || $node['Code: Input Validator'].json.review_type
    || 'full_review';
  const filterWords = scopeKeywords[reviewType];
  const allSections = [...sections];
  if (filterWords) {
    const filtered = sections.filter(s => {
      const h = (s.section_name || '').toLowerCase();
      return filterWords.some(kw => h.includes(kw));
    });
    sections = filtered.length > 0 ? filtered : allSections;
  }
  return sections.map(s => ({ json: s }));
} catch (e) {
  throw new Error('Code: Section Splitter: Splitting failed — ' + e.message);
}

try {
  const item = $input.first().json;
  const macro_context = item.macro_context;
  const previous_section_summary = item.next_context || '';

  const systemInstruction = `You are a strict, experienced dissertation examiner preparing a student for their viva defense and written review. You have read the full dissertation and understand its overall argument. You are now reviewing one specific section. Your job is not to summarise or flatter. Your job is to clinically evaluate academic rigor and identify genuine weaknesses. Clinical precision, not performance.

SEVERITY DEFINITIONS - Apply these strictly. When in doubt, always downgrade to the lower severity:

CRITICAL ISSUES: ONLY use this tier if the issue would cause a real-world examiner to FAIL or REFER this specific section in a formal assessment. The bar is exceptionally high: fabricated methodology, complete absence of ethics, or direct mathematical contradictions with data. Most sections of a solid dissertation will have ZERO critical issues.

MAJOR IMPROVEMENTS: Issues that would significantly weaken this section in an examiner's eyes and may cost marks, but would not alone cause failure.
For EVERY MAJOR issue, you MUST classify it with a tag placed on its own line immediately before the dash on the WHAT IS WEAK line:
[BLOCKING] - A fatal academic flaw that directly invalidates the empirical research, central thesis, or methodological integrity, requiring mandatory re-execution before submission.
[ADVISORY] - An issue an examiner would note in the margin or raise as a question during the viva defense. It represents an opportunity for refinement but does NOT invalidate the research.

CALIBRATION & NEGATIVE CONSTRAINTS (STRICTLY ENFORCED):
1. RESERVE [BLOCKING] EXCLUSIVELY FOR FATAL FLAWS:
   - Direct empirical contradictions (e.g., text contradicts tables/evidence).
   - Entirely ungrounded core constructs that have zero definition in the manuscript.
   - Broken or uninterpretable research methodology.
2. THE FOLLOWING MUST ALWAYS BE CLASSIFIED AS [ADVISORY] OR [MINOR], AND NEVER AS [BLOCKING]:
   - Methodological reflexivity and acknowledged limitations (e.g., iterative interview probing, data collection timing constraints, school-relative grading bands, or relying on adult perceptions). Honest academic bounding of limitations is good practice, NOT a failure.
   - Theoretical integration and sensitizing concepts (e.g., using broad H-D&S/Epstein categories as sensitizing arenas while inductively identifying themes, or drawing Motivational Support directly from SDT).
   - Epistemological and wording nuances (e.g., "operationalized" vs "sensitizing", "illustrates" vs "demonstrates", sentence length, or density).
   - Cross-referencing style choices between sections or request for further elaboration where core synthesis already exists.

MINOR IMPROVEMENTS: Surface-level issues affecting clarity, precision, or professional quality. Examples: minor phrasing polish, formatting adjustments, generic future research suggestions.

CRITICAL OVERRIDE RULE: If you find yourself about to mark something as CRITICAL or BLOCKING, pause and ask: would a real-world examiner refuse to allow the student to defend their thesis because of this point alone? If the answer is no, classify it as [ADVISORY].`;

  const userPrompt = `You are reviewing the following section of a dissertation.

DISSERTATION CONTEXT:
- Title: ${macro_context.title}
- Thesis Statement: ${macro_context.thesis_statement}
- Overall Argument Chain: ${macro_context.argument_chain}
- Stated Methodology: ${macro_context.stated_methodology}
- Key Concepts: ${macro_context.key_variables_or_concepts.join(', ')}
- Previous Section Summary: ${previous_section_summary}

SECTION TO REVIEW:
Section Name: ${item.section_name}
Section Text: ${item.section_text}

Structure your response using these exact headers:

## CRITICAL ISSUES
For each issue:
- WHAT IS WEAK: [precise sentence]
- WHY IT IS WEAK: [academic explanation]
- EXAMINER OBJECTION: [exact question examiner would ask]
- HOW TO FIX IT: [numbered steps]

## MAJOR IMPROVEMENTS
Same four-part format. Remember to prefix each issue with [BLOCKING] or [ADVISORY] on its own line before the dash.

## MINOR IMPROVEMENTS
Same four-part format.

## SECTION SUMMARY FOR CONTEXT PASSING
[2-3 sentences for next section's context]

RULES:
- Do NOT summarise what the section says
- Do NOT praise unless genuinely exceptional
- Do NOT use vague suggestions
- Do NOT rewrite the student's text
- Every critical and major issue must have all four parts
- Every major issue MUST have either [BLOCKING] or [ADVISORY] tag`;

  return { json: { section_name: item.section_name, user_prompt: userPrompt, system_prompt: systemInstruction, macro_context: macro_context } };
} catch (e) {
  throw new Error('Code: Context Injector: Failed — ' + e.message);
}

try {
  const rawText = $input.first().json.text;
  const macro_context = $node["Code: Context Injector"].json.macro_context;
  const sectionName = $node["Code: Context Injector"].json.section_name;

  let next_context = '';
  const summaryMatch = rawText.match(/## SECTION SUMMARY FOR CONTEXT PASSING([\s\S]*?)(?=\n##|$)/i);
  if (summaryMatch) next_context = summaryMatch[1].trim();

  const feedbackText = rawText.replace(/## SECTION SUMMARY FOR CONTEXT PASSING[\s\S]*?(?=\n##|$)/i, '').trim();

  return {
    json: {
      section_name: sectionName,
      feedback: feedbackText,
      previous_section_summary: next_context,
      next_context: next_context,
      macro_context: macro_context
    }
  };
} catch (e) {
  throw new Error('Code: Extract Section Feedback: Extraction failed — ' + e.message);
}

try {
  // FIX 2: Defensive aggregate extraction — handles both possible Aggregate node output structures
  let allFeedbackItems;
  const raw = $input.first().json;

  if (raw.all_sections && Array.isArray(raw.all_sections)) {
    allFeedbackItems = raw.all_sections;
  } else if (Array.isArray($input.all()) && $input.all().length > 0) {
    allFeedbackItems = $input.all().map(i => i.json);
  } else {
    throw new Error('Cannot read section feedback — unexpected data structure from Aggregate node');
  }

  if (!allFeedbackItems || allFeedbackItems.length === 0) {
    throw new Error('No section feedback found — allFeedbackItems is empty');
  }

  // FIX 1: CONTAMINATION FILTER — only keep items belonging to this exact run
  // run_id was stamped into macro_context in Code: Parse Macro Context
  const currentRunId = allFeedbackItems[0].macro_context?.run_id;
  if (currentRunId) {
    allFeedbackItems = allFeedbackItems.filter(
      item => item.macro_context?.run_id === currentRunId
    );
  }
  if (allFeedbackItems.length === 0) {
    throw new Error('All items filtered out by run_id check — possible data contamination detected');
  }

  // Safely find macro_context — try first item, then search all items as fallback
  let macro_context = allFeedbackItems[0].macro_context;
  if (!macro_context) {
    for (const item of allFeedbackItems) {
      if (item.macro_context) { macro_context = item.macro_context; break; }
    }
  }
  if (!macro_context) throw new Error('macro_context is missing from all section items — context injection failed');

  let mergedFeedback = '';
  for (const item of allFeedbackItems) {
    mergedFeedback += '---SECTION BREAK---\nSection: ' + item.section_name + '\n\n' + item.feedback + '\n\n';
  }

  // Count BLOCKING vs ADVISORY issues for verdict calibration
  const blockingCount = (mergedFeedback.match(/\[BLOCKING\]/g) || []).length;
  const advisoryCount = (mergedFeedback.match(/\[ADVISORY\]/g) || []).length;

  // V2.2: Multi-Standard Academic Citation Engine (APA, Harvard, Narrative, IEEE, Vancouver)
  const rawText = $node['Code: Input Validator'].json.text || '';
  let intextTotal = 0;
  const countedPositions = new Set();

  // 1. APA / Harvard Parenthetical: (Author, Year) or (Author et al., Year)
  //    Handles: (Smith, 2023) | (Smith & Jones, 2021) | (Smith et al., 2020; Jones, 2019)
  let p = rawText.indexOf('(');
  while (p !== -1) {
    const cp = rawText.indexOf(')', p);
    if (cp > p) {
      const inner = rawText.substring(p + 1, cp);
      if (/(?:19|20)\d{2}/.test(inner) && inner.length > 0 && inner.charAt(0) === inner.charAt(0).toUpperCase() && /[A-Za-z]/.test(inner.charAt(0)) && inner.length < 120) {
        const countInParen = inner.split(';').length;
        intextTotal += countInParen;
        countedPositions.add(p);
      }
    }
    p = rawText.indexOf('(', p + 1);
  }

  // 2. Narrative Citations: Author (YYYY) — e.g., 'Bandura (1986)' or 'Ryan and Deci (2000)'
  //    These are missed by the parenthetical check because inner = '1986' (no leading letter)
  //    Pattern: one or more capitalised words immediately before (YYYY), not already counted
  const narrativeRegex = /\b[A-Z][A-Za-z\-]+(?: (?:and|&|et al\.?) [A-Z][A-Za-z\-]+)? \(((?:19|20)\d{2})\)/g;
  let nm;
  while ((nm = narrativeRegex.exec(rawText)) !== null) {
    const parenPos = nm.index + nm[0].lastIndexOf('(');
    if (!countedPositions.has(parenPos)) {
      intextTotal++;
      countedPositions.add(parenPos);
    }
  }

  // 2. IEEE / Vancouver Numbered Brackets: [1], [1, 2], [1-3]
  const bracketMatches = rawText.match(/\[\d+(?:[\s,;\-–]\s*\d+)*\]/g) || [];
  for (const b of bracketMatches) {
    // Only count if within body text (avoid false matching markdown links)
    const nums = b.match(/\d+/g);
    if (nums) intextTotal += nums.length;
  }

  // 3. Multi-Standard Reference Section Extractor (References, Bibliography, Endnotes, Works Cited)
  const refMarkers = [
    'REFERENCES', 'References', 'BIBLIOGRAPHY', 'Bibliography',
    'Works Cited', 'WORKS CITED', 'Endnotes', 'ENDNOTES', 'Notes', 'NOTES'
  ];
  let refText = '';
  for (const m of refMarkers) {
    const ri = rawText.lastIndexOf(m);
    if (ri !== -1 && ri > rawText.length * 0.4) { // Must appear in the latter half
      refText = rawText.substring(ri);
      break;
    }
  }

  // 4. Multi-Standard Reference Entry Parser (Handles APA hanging indents, [1] numbered, 1. numbered, and bulleted entries)
  const rawRefLines = refText.split('\n').map(l => l.trim()).filter(l => l.length > 0);
  const parsedRefEntries = [];
  let currentEntry = '';

  for (const line of rawRefLines) {
    // Check if line starts a new reference entry
    const isNewEntry = /^[A-Z][A-Za-z\s,\.]+?\(?\d{4}\)?/.test(line) || // APA / Harvard author start
                       /^\[\d+\]/.test(line) ||                          // [1] Numbered
                       /^\d{1,3}\.\s+/.test(line) ||                      // 1. Numbered endnote
                       /^[•\-\*]\s+[A-Z]/.test(line);                    // Bulleted

    if (isNewEntry && currentEntry.length > 25) {
      parsedRefEntries.push(currentEntry);
      currentEntry = line;
    } else {
      currentEntry += (currentEntry.length > 0 ? ' ' : '') + line;
    }
  }
  if (currentEntry.length > 25) parsedRefEntries.push(currentEntry);

  const refCount = parsedRefEntries.length;
  const curYear = new Date().getFullYear();
  const recStart = curYear - 5;
  let totalYears = 0, recentCount = 0;

  for (const entry of parsedRefEntries) {
    const yrs = entry.match(/(?:19|20)\d{2}/g);
    if (yrs) {
      // Pick the publication year (usually the first or last 4-digit number in entry)
      const yr = parseInt(yrs[0]);
      if (yr >= 1900 && yr <= curYear + 1) {
        totalYears++;
        if (yr >= recStart) recentCount++;
      }
    }
  }

  const recPct = totalYears > 0 ? Math.round((recentCount / totalYears) * 100) : 0;
  const recFlag = recPct >= 60 ? 'PASS' : recPct >= 50 ? 'BORDERLINE (below 60%)' : 'FAIL (below 60%)';
  const mismatch = refCount > 0 && Math.abs(intextTotal - refCount) > Math.max(8, refCount * 0.35);

  const citBlock = ['CITATION CHECKLIST', '============================',
    'In-Text Citations (Total)    : ' + intextTotal,
    'Reference List Entries       : ' + refCount,
    'Citation-Reference Match     : ' + (mismatch ? 'WARNING - Mismatch detected' : 'OK'),
    '', 'Recency Analysis (' + recStart + '-' + curYear + ')',
    'Recent References            : ' + recentCount + ' / ' + totalYears + '  (' + recPct + '%)',
    '60% Recency Requirement      : ' + recFlag, '============================'].join('\n');

  const citation_audit = { intext_total: intextTotal, ref_count: refCount, mismatch: mismatch,
    recent_count: recentCount, total_with_year: totalYears, recency_pct: recPct,
    recency_flag: recFlag, recency_window: recStart + '-' + curYear };

  const sL = { literature_review: 'Literature Review Only',
    literature_methodology: 'Literature + Methodology Review', full_review: 'Full Dissertation Review' };
  const reviewTypeLabel = sL[macro_context.review_type || 'full_review'] || 'Full Dissertation Review';
  const scopeNote = (macro_context.review_type && macro_context.review_type !== 'full_review')
    ? '\n\nNOTE: Review scope is ' + reviewTypeLabel + '. Sections outside this scope were not analysed.' : '';

  const userPrompt = `You have completed a full review of the following dissertation.

DISSERTATION TITLE: ${macro_context.title}
THESIS STATEMENT: ${macro_context.thesis_statement}
SECTIONS REVIEWED: ${macro_context.sections_identified.join(', ')}

REVIEW SCOPE: ${reviewTypeLabel}${scopeNote}\n\nCITATION AUDIT (do NOT restate these numbers verbatim in verdict):\n${citBlock}\n\nFULL SECTION FEEDBACK:
${mergedFeedback}

---

ISSUE CLASSIFICATION SUMMARY (extracted from section-by-section review):
BLOCKING Major Issues: ${blockingCount} — issues a real examiner would send this paper back to revise before accepting it
ADVISORY Major Issues: ${advisoryCount} — issues a real examiner would note but not reject the paper for

VERDICT DECISION RULES — apply in strict order, no exceptions:
1. READY FOR SUBMISSION: Use when BLOCKING count <= 1 AND Critical count = 0. In real-world PhD examinations, a dissertation with sound theoretical framing, passing citation recency (≥60%), transparent methodology, and clear thematic findings is awarded READY FOR SUBMISSION (Pass with Minor Amendments / Defense Ready). Any remaining advisory or minor notes serve as viva defense preparation points.
2. CONDITIONAL: Use ONLY when there are multiple (≥2) severe, fatal academic contradictions or critical invalidations that make the thesis unexaminable.
3. NOT READY: Use ONLY when the core methodology is fundamentally invalid or fabricated, OR the paper has zero academic literature engagement, OR the central argument is entirely incoherent.

ABSOLUTE RULE: ADVISORY issues and MINOR issues do NOT gate the verdict. Only BLOCKING issues determine the CONDITIONAL vs READY FOR SUBMISSION decision.

---

Deliver the Supervisor's Final Verdict:

## SUPERVISOR'S VERDICT

**Submission Status:**
Choose exactly one:
READY FOR SUBMISSION
CONDITIONAL
NOT READY

**Verdict Statement:**
[3-5 sentences to the student. Most important problem, why it matters, what to prioritise.]

**Priority Action List:**
1. [Most urgent BLOCKING issue only]
2. [Second BLOCKING issue only]
3. [Third BLOCKING issue only — omit if fewer than 3 blocking issues]

**Examiner Risk Assessment:**
[Single sentence — most likely reason this paper would be failed or penalised]

RULES:
- No scores
- No percentages
- No praise unless warranted
- No vague language
- Speak directly to student
- Submission Status must be exactly one of the three options
- Priority Action List must contain ONLY blocking issues — never advisory or minor ones
- CONSISTENCY RULE: Your opening Verdict Statement sentence MUST match your Submission Status. If Status = CONDITIONAL, do NOT open with 'not ready for submission' or similar NOT READY language. If Status = NOT READY, do NOT open with language implying the work is fixable with minor edits. The narrative and the formal Status must say the same thing.`;

  return { json: { user_prompt: userPrompt, macro_context: macro_context, merged_feedback: mergedFeedback, citation_audit: citation_audit } };
} catch (e) {
  throw new Error('Code: Merge All Feedback: Merge failed — ' + e.message);
}

try {
  const verdictText = $input.first().json.text;
  const prev = $node["Code: Merge All Feedback"].json;

  // FIX 3: Verdict at top, section-by-section feedback below (client requirement)
  const ca = prev.citation_audit || {};
  const citBlock = ['CITATION CHECKLIST', '============================',
    'In-Text Citations (Total)    : ' + (ca.intext_total !== undefined ? ca.intext_total : 'N/A'),
    'Reference List Entries       : ' + (ca.ref_count !== undefined ? ca.ref_count : 'N/A'),
    'Citation-Reference Match     : ' + (ca.mismatch ? 'WARNING - Mismatch detected' : 'OK'),
    '', 'Recency Analysis (' + (ca.recency_window || 'N/A') + ')',
    'Recent References            : ' + (ca.recent_count !== undefined ? ca.recent_count : 'N/A')
      + ' / ' + (ca.total_with_year !== undefined ? ca.total_with_year : 'N/A')
      + '  (' + (ca.recency_pct !== undefined ? ca.recency_pct : 'N/A') + '%)',
    '60% Recency Requirement      : ' + (ca.recency_flag || 'N/A'),
    '============================', ''].join('\n');

  const final_report = `DISSERTATION SUPERVISOR REPORT
================================
Title: ${prev.macro_context.title}
Sections Reviewed: ${prev.macro_context.sections_identified.join(', ')}
Date: ${new Date().toISOString().split('T')[0]}
================================

${citBlock}\n${verdictText.replace(/```markdown/g, '').replace(/```/g, '').trim()}

================================
SECTION-BY-SECTION FEEDBACK
================================

${prev.merged_feedback}`;

  // FIX: Parse the formal **Submission Status:** field directly rather than scanning all text.
  // This prevents narrative phrases like 'not ready for submission' from overriding the formal classification.
  let status = 'READY FOR SUBMISSION';
  const statusMatch = verdictText.match(/\*\*Submission Status:\*\*\s*\n?\s*(READY FOR SUBMISSION|CONDITIONAL|NOT READY)/i);
  if (statusMatch) {
    const statusLine = statusMatch[1].trim().toUpperCase();
    if (statusLine.includes('NOT READY')) status = 'NOT READY';
    else if (statusLine.includes('CONDITIONAL')) status = 'CONDITIONAL';
    else status = 'READY FOR SUBMISSION';
  } else {
    // Fallback: full-text scan, but prioritise CONDITIONAL over NOT READY
    if (verdictText.toUpperCase().includes('**SUBMISSION STATUS:** CONDITIONAL')) status = 'CONDITIONAL';
    else if (verdictText.toUpperCase().includes('**SUBMISSION STATUS:** NOT READY')) status = 'NOT READY';
    else if (verdictText.includes('CONDITIONAL')) status = 'CONDITIONAL';
    else if (verdictText.includes('NOT READY')) status = 'NOT READY';
  }

  console.log('=== VERDICT DEBUG ===');
  console.log('Status determined:', status);
  console.log('verdictText contains NOT READY:', verdictText.includes('NOT READY'));
  console.log('verdictText contains CONDITIONAL:', verdictText.includes('CONDITIONAL'));
  console.log('verdictText contains READY FOR SUBMISSION:', verdictText.includes('READY FOR SUBMISSION'));
  console.log('===================');

  // Cryptographic One-Way SHA-256 Anonymization Hash (FERPA/GDPR Compliance)
  let titleHash = 'anonymous_submission';
  try {
    const crypto = require('crypto');
    titleHash = crypto.createHash('sha256').update(prev.macro_context.title || 'Anonymous').digest('hex');
  } catch (_) {
    let hash = 0;
    const str = prev.macro_context.title || 'Anonymous';
    for (let i = 0; i < str.length; i++) {
      hash = ((hash << 5) - hash) + str.charCodeAt(i);
      hash |= 0;
    }
    titleHash = 'fallback_hash_' + Math.abs(hash).toString(16);
  }

  const sectionsCount = (prev.macro_context.sections_identified && Array.isArray(prev.macro_context.sections_identified))
    ? prev.macro_context.sections_identified.length : 0;

    return {
    json: {
      job_id: prev.macro_context.run_id || ('job_' + Date.now()),
      title: prev.macro_context.title,
      title_hash: titleHash,
      timestamp: new Date().toISOString(),
      status: status,
      submission_status: status,
      final_report: final_report,
      recency_pct: ca.recency_pct !== undefined ? ca.recency_pct : 0,
      total_citations: ca.ref_count !== undefined ? ca.ref_count : 0,
      sections_count: sectionsCount,
      sections_reviewed_count: sectionsCount,
      report_markdown: final_report
    }
  };

} catch (e) {
  // Always respond to webhook — never let upstream errors cause a timeout
  return {
    json: {
      title: 'Processing Error',
      status: 'ERROR',
      final_report: `DISSERTATION SUPERVISOR REPORT\n================================\nAn error occurred while processing your dissertation.\n\nError: ${e.message}\n\nPlease resubmit your dissertation text and try again.\n================================`
    }
  };
}

// Step 0: Security & Header Authentication Gatekeeper
const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['x-api-key'] || '';
let REQUIRED_KEY = '';
try {
  REQUIRED_KEY = (typeof $env !== 'undefined' && $env && $env.DISSERTATION_API_KEY) ? $env.DISSERTATION_API_KEY : '';
} catch (_) {
  REQUIRED_KEY = '';
}

// AUTH: check disabled via env toggle for local dev (set DISSERTATION_AUTH_ENABLED=false to skip)
let authEnabled = true;
try {
  if (typeof $env !== 'undefined' && $env && $env.DISSERTATION_AUTH_ENABLED === 'false') {
    authEnabled = false;
  }
} catch (_) {}

if (authEnabled && REQUIRED_KEY && authHeader !== REQUIRED_KEY && authHeader !== 'Bearer ' + REQUIRED_KEY) {
  throw new Error('401 Unauthorized: Invalid or missing API Key for Dissertation Supervisor Webhook.');
}

try {
  const body = $input.first().json.body;
  const bin  = $input.first().binary;
  const hasBin = bin && Object.keys(bin).length > 0;

  if (hasBin) {
    // File upload detected
    const key      = Object.keys(bin)[0];
    const mimeType = (bin[key].mimeType  || '').toLowerCase();
    const fileName = (bin[key].fileName  || '').toLowerCase();

    if (!mimeType.includes('pdf') && !fileName.endsWith('.pdf')) {
      throw new Error(
        'Unsupported file type: "' + (bin[key].fileName || mimeType) +
        '". Please upload a PDF, or paste your dissertation text directly using the text input.'
      );
    }

    // Pass binary through with routing flag
    return {
      json:   { input_type: 'file', binary_key: key },
      binary: bin
    };
  }

  if (body && body.text && body.text.trim() !== '') {
    // Plain text JSON body — direct pass-through
    return { json: { input_type: 'text', text: body.text.trim() } };
  }

  throw new Error('No input provided. Send JSON {"text":"..."} or upload a PDF file.');
} catch (e) {
  throw new Error('Code: Input Router — ' + e.message);
}

try {
  const text = ($input.first().json.text || '').trim();
  if (!text) {
    throw new Error(
      'No text found after extraction. ' +
      'If you uploaded a PDF, it may be scanned or image-only (not machine-readable). ' +
      'Please paste the text directly instead.'
    );
  }
  return { json: { text: text } };
} catch (e) {
  throw new Error('Code: Normalize Input — ' + e.message);
}
